/// Aliases: (alias, flag, the deprecation warning after `<vm> warning: `).
#[rustfmt::skip]
pub(crate) const ALIASES: &[(&str, &str, &str)] = &[
    ("CreateMinidumpOnCrash", "CreateCoredumpOnCrash", "Option CreateMinidumpOnCrash was deprecated in version 9.0 and will likely be removed in a future release. Use option CreateCoredumpOnCrash instead."),
];

/// Is `name` a `develop` flag, and is it a `bool`?
pub(crate) fn develop(name: &str) -> Option<bool> {
    DEVELOP
        .binary_search_by(|(n, _)| n.cmp(&name))
        .ok()
        .map(|i| DEVELOP[i].1)
}
